package com.hospital.smartqueue.patient.domain;
import jakarta.persistence.*; import org.hibernate.annotations.UuidGenerator; import java.time.*; import java.util.*;
@Entity @Table(name="patients") public class Patient {
 @Id @GeneratedValue @UuidGenerator private UUID id; @Column(name="hospital_id",updatable=false,nullable=false) private UUID hospitalId; @Column(name="patient_number",updatable=false,nullable=false) private String patientNumber;
 private String firstName,lastName; @Column(name="canonical_first_name") private String canonicalFirstName; @Column(name="canonical_last_name") private String canonicalLastName; private LocalDate dateOfBirth; @Enumerated(EnumType.STRING) private Gender gender; @Column(name="mobile_number") private String mobileNumber; @Column(name="normalized_mobile_number") private String normalizedMobileNumber; private String email,address; @Column(name="emergency_contact_name") private String emergencyContactName; @Column(name="emergency_contact_relationship") private String emergencyContactRelationship; @Column(name="emergency_contact_mobile_number") private String emergencyContactMobileNumber; @Version private long version; protected Patient(){}
 public Patient(UUID h,String n,String fn,String ln,LocalDate dob,Gender g,String m,String e,String a,EmergencyContact c){hospitalId=h;patientNumber=n;apply(fn,ln,dob,g,m,e,a,c);} public void apply(String fn,String ln,LocalDate dob,Gender g,String m,String e,String a,EmergencyContact c){firstName=fn.strip();lastName=ln.strip();canonicalFirstName=firstName.toLowerCase(Locale.ROOT);canonicalLastName=lastName.toLowerCase(Locale.ROOT);dateOfBirth=dob;gender=g;mobileNumber=m.strip();normalizedMobileNumber=mobileNumber.replaceAll("\\s+","");email=e;address=a;emergencyContactName=c==null?null:c.name();emergencyContactRelationship=c==null?null:c.relationship();emergencyContactMobileNumber=c==null?null:c.mobileNumber();}
 public UUID getId(){return id;} public UUID getHospitalId(){return hospitalId;} public String getPatientNumber(){return patientNumber;} public long getVersion(){return version;} public String getFirstName(){return firstName;} public String getLastName(){return lastName;} public LocalDate getDateOfBirth(){return dateOfBirth;} public Gender getGender(){return gender;} public String getMobileNumber(){return mobileNumber;} public String getEmail(){return email;} public String getAddress(){return address;}
}
